    "Content-Type": "application/json",
  },
});

type RetryExceptionProps = {
  exception: any;
  response: { token: string; companyID: string; userID: string; queue: any[] };
  resolve: any;
};

type RejectExceptionProps = {
  reject: any;
  error: any;
