         ? (productAuthorities as Record<string, { anyAuthority?: boolean }>).AUTO_COLLECTION_REGISTRATION ??
           (productAuthorities as Record<string, { anyAuthority?: boolean }>).auto_collection_registration ??
           (productAuthorities as { anyAuthority?: boolean })
