    const hasCustomRadius = /(^|\s)(acs:)?rounded(-[a-z0-9]+)?!?(\s|$)/.test(className);
    const defaultRadius = hasCustomRadius ? "" : "acs:rounded-md";

    return (
      <input
        type="text"
        name={name}
        value={value}
        onChange={onChange}
        placeholder={placeholder}
        required={required}
