+import { customAxios as briAxios } from "@bri/addons-auth-provider/dist/services";
+import { HOST_AUTH_EVENT } from "./host-auth-events";
+
+interface CachedResponse {
+  data: unknown;
+  status: number;
+  statusText: string;
+  headers: Record<string, unknown>;
+  timestamp: number;
+}
+
+const DEDUPE_ENDPOINTS = ["/menu/me", "/auth/me"] as const;
+const CACHE_TTL_MS = 5000;
+
+let isInstalled = false;
+const inFlightRequests = new Map<string, Promise<unknown>>();
+const responseCache = new Map<string, CachedResponse>();
+
+export function clearAuthRequestCache() {
+  inFlightRequests.clear();
+  responseCache.clear();
+}
+
+function installCoalescingAdapter(axiosInstance: any) {
+  if (!axiosInstance || typeof axiosInstance.request !== "function") return;
+
+  const originalRequest = axiosInstance.request.bind(axiosInstance);
+
+  axiosInstance.request = async function (configOrUrl: any, maybeConfig?: any) {
+    const config = typeof configOrUrl === "string" ? { url: configOrUrl, ...(maybeConfig || {}) } : { ...configOrUrl };
+    const url = config.url || "";
+    const isTarget = DEDUPE_ENDPOINTS.some((endpoint) => url.includes(endpoint));
+
+    if (!isTarget || config.method?.toLowerCase() === "delete") {
+      return originalRequest(config);
+    }
+
+    const token =
+      (typeof config.data === "string" ? config.data : JSON.stringify(config.data || "")) +
+      String(config.headers?.Authorization || "");
+    const cacheKey = `${url}:${token}`;
+    const now = Date.now();
+
+    const cached = responseCache.get(cacheKey);
+    if (cached && now - cached.timestamp < CACHE_TTL_MS) {
+      return {
+        data: cached.data,
+        status: cached.status,
+        statusText: cached.statusText,
+        headers: cached.headers,
+        config,
+      };
+    }
+
+    const existing = inFlightRequests.get(cacheKey);
+    if (existing) {
+      return existing;
+    }
+
+    const promise = (async () => {
+      try {
+        const res = await originalRequest(config);
+        if (res && res.status >= 200 && res.status < 300) {
+          responseCache.set(cacheKey, {
+            data: res.data,
+            status: res.status,
+            statusText: res.statusText,
+            headers: res.headers,
+            timestamp: Date.now(),
+          });
+        }
+        return res;
+      } finally {
+        inFlightRequests.delete(cacheKey);
+      }
+    })();
+
+    inFlightRequests.set(cacheKey, promise);
+    return promise;
+  };
+}
+
+export function setupAuthRequestDeduplication() {
+  if (typeof window === "undefined" || isInstalled) return;
+  installCoalescingAdapter(briAxios);
+
+  window.addEventListener(HOST_AUTH_EVENT, () => {
+    clearAuthRequestCache();
+  });
+
+  window.addEventListener("storage", (event) => {
+    if (event.key === "access-token") {
+      clearAuthRequestCache();
+    }
+  });
+
+  isInstalled = true;
+}
